-- =====================================================
-- CultureRadar - Export SQL complet (schema + donnees)
-- Genere le 2026-04-21T12:18:08.333498
-- =====================================================

-- =====================================================
-- CultureRadar - Schema de base de donnees
-- La boussole culturelle dont vous avez besoin
-- =====================================================

PRAGMA foreign_keys = ON;

-- =====================================================
-- UTILISATEURS (B2C + B2B + ADMIN)
-- =====================================================
CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    nom TEXT NOT NULL,
    prenom TEXT,
    role TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'pro', 'admin')),
    telephone TEXT,
    ville TEXT,
    code_postal TEXT,
    latitude REAL,
    longitude REAL,
    avatar TEXT,
    bio TEXT,
    subscription_type TEXT DEFAULT 'free' CHECK (subscription_type IN ('free', 'premium', 'pro_local', 'enterprise')),
    subscription_ends_at DATETIME,
    newsletter INTEGER DEFAULT 0,
    accessibility_needs TEXT,  -- JSON: {wheelchair, hearing, vision, cognitive}
    mobility_mode TEXT DEFAULT 'transit',  -- walk, bike, transit, car
    max_distance_km INTEGER DEFAULT 15,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    last_login DATETIME,
    active INTEGER DEFAULT 1
);

CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);
CREATE INDEX IF NOT EXISTS idx_users_role ON users(role);

-- =====================================================
-- PREFERENCES CULTURELLES (1 user -> N categories)
-- =====================================================
CREATE TABLE IF NOT EXISTS user_preferences (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    category TEXT NOT NULL,
    weight REAL DEFAULT 1.0,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE(user_id, category)
);

CREATE INDEX IF NOT EXISTS idx_userpref_user ON user_preferences(user_id);

-- =====================================================
-- LIEUX CULTURELS (musees, theatres, salles, etc.)
-- =====================================================
CREATE TABLE IF NOT EXISTS places (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    owner_id INTEGER,  -- user pro qui gere le lieu (NULL = ajoute par admin)
    nom TEXT NOT NULL,
    description TEXT,
    category TEXT NOT NULL,  -- musee, theatre, salle_concert, galerie, cinema, bibliotheque, mediatheque, lieu_patrimoine, espace_independant
    adresse TEXT NOT NULL,
    code_postal TEXT,
    ville TEXT NOT NULL,
    latitude REAL NOT NULL,
    longitude REAL NOT NULL,
    telephone TEXT,
    email TEXT,
    site_web TEXT,
    horaires TEXT,  -- JSON
    accessibility TEXT,  -- JSON: {wheelchair, audio, visuel, ...}
    image_url TEXT,
    is_independent INTEGER DEFAULT 0,  -- badge CultureRadar si independant/meconnu
    verified INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS idx_places_ville ON places(ville);
CREATE INDEX IF NOT EXISTS idx_places_category ON places(category);
CREATE INDEX IF NOT EXISTS idx_places_owner ON places(owner_id);

-- =====================================================
-- EVENEMENTS CULTURELS
-- =====================================================
CREATE TABLE IF NOT EXISTS events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    place_id INTEGER,
    organizer_id INTEGER,  -- user pro qui a cree l evenement
    titre TEXT NOT NULL,
    slug TEXT UNIQUE,
    description TEXT,
    category TEXT NOT NULL,  -- musique, theatre, patrimoine, exposition, danse, cinema, litterature, conference, atelier, festival, jeune_public
    tags TEXT,  -- CSV: classique,gratuit,plein-air
    date_debut DATETIME NOT NULL,
    date_fin DATETIME,
    duree_minutes INTEGER,
    prix_min REAL DEFAULT 0,
    prix_max REAL,
    gratuit INTEGER DEFAULT 0,
    places_disponibles INTEGER,
    outdoor INTEGER DEFAULT 0,  -- pour recommandation en fonction de la meteo
    accessibility TEXT,  -- JSON
    age_min INTEGER,
    age_max INTEGER,
    langue TEXT DEFAULT 'fr',
    image_url TEXT,
    source TEXT DEFAULT 'culture-radar',  -- culture-radar, openagenda
    external_id TEXT,
    status TEXT DEFAULT 'published' CHECK (status IN ('draft', 'published', 'cancelled', 'finished')),
    is_promoted INTEGER DEFAULT 0,  -- paye pour etre mis en avant
    promoted_until DATETIME,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (place_id) REFERENCES places(id) ON DELETE SET NULL,
    FOREIGN KEY (organizer_id) REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS idx_events_category ON events(category);
CREATE INDEX IF NOT EXISTS idx_events_date ON events(date_debut);
CREATE INDEX IF NOT EXISTS idx_events_place ON events(place_id);
CREATE INDEX IF NOT EXISTS idx_events_organizer ON events(organizer_id);
CREATE INDEX IF NOT EXISTS idx_events_status ON events(status);
CREATE INDEX IF NOT EXISTS idx_events_promoted ON events(is_promoted);

-- =====================================================
-- RESERVATIONS (envies, reservations, participations)
-- =====================================================
CREATE TABLE IF NOT EXISTS reservations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    event_id INTEGER NOT NULL,
    status TEXT DEFAULT 'envie' CHECK (status IN ('envie', 'reserve', 'participe', 'annule')),
    nb_places INTEGER DEFAULT 1,
    note_personnelle TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,
    UNIQUE(user_id, event_id)
);

CREATE INDEX IF NOT EXISTS idx_reservations_user ON reservations(user_id);
CREATE INDEX IF NOT EXISTS idx_reservations_event ON reservations(event_id);

-- =====================================================
-- AVIS / EVALUATIONS
-- =====================================================
CREATE TABLE IF NOT EXISTS reviews (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    event_id INTEGER NOT NULL,
    note INTEGER NOT NULL CHECK (note BETWEEN 1 AND 5),
    commentaire TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,
    UNIQUE(user_id, event_id)
);

CREATE INDEX IF NOT EXISTS idx_reviews_event ON reviews(event_id);

-- =====================================================
-- PROMOTIONS PAYEES (un lieu paie pour mettre en avant)
-- =====================================================
CREATE TABLE IF NOT EXISTS promotions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,  -- qui a achete la promo
    montant REAL NOT NULL,
    pack TEXT NOT NULL,  -- boost_7j, premium_30j, sponsored
    date_debut DATETIME NOT NULL,
    date_fin DATETIME NOT NULL,
    payment_status TEXT DEFAULT 'paye' CHECK (payment_status IN ('en_attente', 'paye', 'rembourse', 'echec')),
    payment_ref TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_promos_event ON promotions(event_id);
CREATE INDEX IF NOT EXISTS idx_promos_user ON promotions(user_id);

-- =====================================================
-- ABONNEMENTS PREMIUM (B2C et B2B)
-- =====================================================
CREATE TABLE IF NOT EXISTS subscriptions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    plan TEXT NOT NULL,  -- free, premium, pro_local, enterprise
    prix_mensuel REAL,
    date_debut DATETIME NOT NULL,
    date_fin DATETIME,
    status TEXT DEFAULT 'actif' CHECK (status IN ('actif', 'annule', 'expire', 'suspendu')),
    payment_ref TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_subs_user ON subscriptions(user_id);

-- =====================================================
-- LOGS / ANALYTICS (evenements tracks dans la plateforme)
-- =====================================================
CREATE TABLE IF NOT EXISTS analytics_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER,
    session_id TEXT,
    event_type TEXT NOT NULL,  -- page_view, event_view, click_reco, search, reservation_added
    event_data TEXT,  -- JSON
    ip_address TEXT,
    user_agent TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS idx_analytics_type ON analytics_events(event_type);
CREATE INDEX IF NOT EXISTS idx_analytics_date ON analytics_events(created_at);
CREATE INDEX IF NOT EXISTS idx_analytics_user ON analytics_events(user_id);

-- =====================================================
-- NOTIFICATIONS (motivantes - encourager la pratique)
-- =====================================================
CREATE TABLE IF NOT EXISTS notifications (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    type TEXT NOT NULL,  -- recommendation, rappel, nouveau_evenement, badge, systeme
    titre TEXT NOT NULL,
    message TEXT NOT NULL,
    url TEXT,
    lu INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_notif_user ON notifications(user_id);
CREATE INDEX IF NOT EXISTS idx_notif_lu ON notifications(lu);

-- =====================================================
-- PARTENARIATS (collectivites, entreprises)
-- =====================================================
CREATE TABLE IF NOT EXISTS partnerships (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nom TEXT NOT NULL,
    type TEXT NOT NULL,  -- collectivite, entreprise, association
    contact_email TEXT,
    contact_nom TEXT,
    description TEXT,
    montant_annuel REAL,
    date_debut DATETIME,
    date_fin DATETIME,
    status TEXT DEFAULT 'actif',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- =====================================================
-- RAPPORTS MENSUELS (generes automatiquement)
-- =====================================================
CREATE TABLE IF NOT EXISTS monthly_reports (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    annee INTEGER NOT NULL,
    mois INTEGER NOT NULL,
    nb_users INTEGER,
    nb_nouveaux_users INTEGER,
    nb_events INTEGER,
    nb_reservations INTEGER,
    nb_reviews INTEGER,
    revenu_abonnements REAL,
    revenu_promotions REAL,
    revenu_partenariats REAL,
    revenu_total REAL,
    top_categories TEXT,  -- JSON
    top_villes TEXT,  -- JSON
    generated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(annee, mois)
);


-- =====================================================
PRAGMA foreign_keys=OFF;

-- DONNEES
-- =====================================================

PRAGMA foreign_keys=OFF;

